def initBatchWorker(
    header,
    maf_file,
    maf_compression,
    index,
    output,
    single_output,
    as_fasta,
    fasta_header,
    expected_species,
    fasta_dedupe,
    verbose,
    profile,
    prefetched_cache=None,
    scaffold_subdirs=False,
    index_file=None,
    scaffold_runs=None,
    loci_tmp_dir=None,
):
    global WORKER_HEADER
    global WORKER_MAF_FILE
    global WORKER_MAF_COMPRESSION
    global WORKER_INDEX
    global WORKER_INDEX_FILE
    global WORKER_SCAFFOLD_RUNS
    global WORKER_OUTPUT
    global WORKER_SINGLE_OUTPUT
    global WORKER_SCAFFOLD_SUBDIRS
    global WORKER_LOCI_TMP_DIR
    global WORKER_AS_FASTA
    global WORKER_FASTA_HEADER
    global WORKER_EXPECTED_SPECIES
    global WORKER_FASTA_DEDUPE
    global WORKER_VERBOSE
    global WORKER_PROFILE
    global WORKER_MAF_FP
    global WORKER_BLOCK_CACHE

    WORKER_HEADER = header
    WORKER_MAF_FILE = maf_file
    WORKER_MAF_COMPRESSION = maf_compression
    WORKER_INDEX = index
    # Block mode streams the index from disk rather than receiving it: the
    # in-memory form is ~288 bytes/block (~67GB for a whole-genome index), and
    # passing it through initargs pickled that whole structure to EVERY worker.
    WORKER_INDEX_FILE = index_file
    WORKER_SCAFFOLD_RUNS = scaffold_runs
    WORKER_OUTPUT = output
    WORKER_SINGLE_OUTPUT = single_output
    WORKER_SCAFFOLD_SUBDIRS = scaffold_subdirs
    WORKER_LOCI_TMP_DIR = loci_tmp_dir
    WORKER_AS_FASTA = as_fasta
    WORKER_FASTA_HEADER = fasta_header
    WORKER_EXPECTED_SPECIES = expected_species
    WORKER_FASTA_DEDUPE = fasta_dedupe
    WORKER_VERBOSE = verbose
    WORKER_PROFILE = profile

    # For gzip input, prefetched_cache already holds every block needed across
    # all regions, decoded in strictly-ascending file order (see
    # prefetchBlockCache) -- inserting it directly here (bypassing
    # getCachedBlockText's eviction check) means every later lookup is a
    # guaranteed hit, so no backward seeks ever happen during real processing.
    WORKER_BLOCK_CACHE = OrderedDict(prefetched_cache) if prefetched_cache else OrderedDict()

    WORKER_MAF_FP = COMMON.openMaf(maf_file, maf_compression, "rb")
    atexit.register(closeBatchWorker)

#############################################################################

def closeBatchWorker():
    global WORKER_MAF_FP
    if WORKER_MAF_FP is not None:
        WORKER_MAF_FP.close()
        WORKER_MAF_FP = None

#############################################################################

def parseIndex(index_file, LOG, mode="block"):
    """
    Parses either a block-level or region-level index file.

    For block mode:
        Returns: { scaffold: [ { ref_start, seq_length, offset_start, offset_end }, ... ] }

    For scaffold mode:
        Returns: { scaffold: (byte_start, byte_end) } — one entry per scaffold
    """
    index = {}

    with open(index_file, "r") as f:
        for line in f:
            if line.startswith("#") or not line.strip():
                continue
            fields = line.strip().split("\t")

            if mode == "block":
                if len(fields) < 7:
                    LOG.warning(f"Skipping malformed index line: {line.strip()}", file=sys.stderr)
                    continue
                scaffold = fields[0]
                try:
                    ref_start = int(fields[1])
                    ref_length = int(fields[2])
                    aln_length = int(fields[3])
                    offset_start = int(fields[6])
                    offset_end = int(fields[7])
                except ValueError:
                    continue
                entry = {
                    "ref_start": ref_start,
                    "ref_length": ref_length,
                    "aln_length": aln_length,
                    "offset_start": offset_start,
                    "offset_end": offset_end
                }
                index.setdefault(scaffold, []).append(entry)

            elif mode == "scaffold":
                if len(fields) != 3:
                    LOG.warning(f"Skipping malformed index line: {line.strip()}", file=sys.stderr)
                    continue
                scaffold = fields[0]
                try:
                    offset_start = int(fields[1])
                    offset_end = int(fields[2])
                except ValueError:
                    continue
                index[scaffold] = (offset_start, offset_end)

    # Sort block entries per scaffold
    if mode == "block":
        for scaffold in index:
            index[scaffold].sort(key=lambda x: x["ref_start"])
            index[scaffold] = {
                "entries": index[scaffold],
                "starts": [entry["ref_start"] for entry in index[scaffold]],
            }

    return index

#############################################################################

def readScaffoldRuns(scaffold_index_file):
    """
    Returns the scaffold index's rows in file order as
    [(scaffold, maf_start_byte, maf_end_byte), ...].

    Each row is a *run* of consecutive blocks for one scaffold, not a unique
    scaffold: a MAF may interleave scaffolds, so the same name can appear more
    than once. tests/example.maf does exactly this (chr4 ... chrX ... chr4),
    and assuming one run per scaffold silently loses the later blocks. The
    block index is in MAF order too, so these runs are also contiguous there.
    """
    runs = []
    with open(scaffold_index_file, "r", encoding="utf-8") as fp:
        for line in fp:
            if line.startswith("#") or not line.strip():
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < 3:
                continue
            try:
                runs.append((fields[0], int(fields[1]), int(fields[2])))
            except ValueError:
                continue
    return runs


def parseIndexLine(line):
    """
    Parses one block-index line into
    (scaffold, ref_start, ref_length, offset_start, offset_end), or None if the
    line is a comment/blank/malformed. Only the columns fetch actually needs.
    """
    if not line or line.startswith("#") or not line.strip():
        return None
    fields = line.rstrip("\n").split("\t")
    if len(fields) < 8:
        return None
    try:
        return (fields[0], int(fields[1]), int(fields[2]), int(fields[6]), int(fields[7]))
    except ValueError:
        return None


def _firstRecordAtOrAfter(fp, offset):
    """
    Seeks to `offset` and returns (record, record_offset) for the first
    COMPLETE record at or after it, or (None, None) at EOF.

    Index lines are variable-length, so there is no arithmetic from "record N"
    to a byte position -- but seeking to an arbitrary byte and discarding the
    partial line lands on a record boundary, which is what makes a binary
    search over the text file possible.
    """
    fp.seek(offset)
    if offset > 0:
        fp.readline()  # discard the (probably partial) line we landed inside
    while True:
        record_offset = fp.tell()
        line = fp.readline()
        if not line:
            return None, None
        record = parseIndexLine(line)
        if record is not None:
            return record, record_offset


def findIndexOffsetForMafByte(index_file, maf_offset, window=8192):
    """
    Byte offset into the block index of the first record whose block starts at
    or after `maf_offset` in the MAF.

    The search key is the block's MAF offset because that is the one column
    guaranteed to increase monotonically through the whole index -- scaffold
    name and ref_start are only sorted *within* a run, and a scaffold can have
    several runs (see readScaffoldRuns).

    Binary search by byte position: seek to a midpoint, skip the partial line,
    compare the first complete record, narrow. ~log2(filesize) probes, so ~35
    on a 35GB index regardless of how many records it holds. Returns an exact
    record boundary, since callers treat offsets as record starts.
    """
    size = os.path.getsize(index_file)
    with open(index_file, "r", encoding="utf-8") as fp:
        lo, hi = 0, size
        while hi - lo > window:
            mid = (lo + hi) // 2
            record, _ = _firstRecordAtOrAfter(fp, mid)
            if record is None:
                hi = mid
                continue
            if record[3] < maf_offset:
                lo = mid
            else:
                hi = mid
        _record, record_offset = _firstRecordAtOrAfter(fp, lo)
        return size if record_offset is None else record_offset


def computeRunIndexOffsets(index_file, runs):
    """
    Maps each scaffold-index run to where its records begin in the block index.

    One binary search per run (61 runs on the hamster data, 455 on the
    241-mammal file) done once at startup -- not per region. Run i's records
    occupy [offsets[i], offsets[i+1]).
    """
    return [findIndexOffsetForMafByte(index_file, maf_start) for _scaffold, maf_start, _maf_end in runs]


def iterIndexRecordsFrom(fp, offset):
    """
    Yields (record, record_offset) from `offset` forward on an already-open
    index handle. Streaming, so memory never scales with index size.

    `offset` MUST be an exact record boundary (both findIndexOffsetForMafByte
    and the record_offset values yielded here are). It deliberately does not
    skip a leading partial line -- doing so would drop the first record when
    resuming from a known boundary.
    """
    fp.seek(offset)
    while True:
        record_offset = fp.tell()
        line = fp.readline()
        if not line:
            return
        record = parseIndexLine(line)
        if record is not None:
            yield record, record_offset


#############################################################################

def parseBed(bed_file, LOG, mode="block"):
    """
    Parses the BED file into a list of region dictionaries.

    In "block" mode: expects at least 3 columns (scaffold, start, end)
    Each region has keys:
        - scaffold (chromosome)
        - start (integer, 0-based)
        - end (integer, non-inclusive)
        - basename (from column 4, if present; otherwise None)

    In "scaffold" mode: accepts 1+ columns; only uses first column (scaffold)
    """
    regions = []
    with open(bed_file, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            fields = line.split()
            if mode == "scaffold":
                scaffold = fields[0]
                region = {"scaffold": scaffold, "start": 0, "end": 0, "id": fields[3] if len(fields) >= 4 else None}
                regions.append(region)
            else:
                # block mode: require at least 3 columns (scaffold/start/end)
                try:
                    scaffold = fields[0]
                    start = int(fields[1])
                    end = int(fields[2])
                    region = {"scaffold": scaffold, "start": start, "end": end, "id": fields[3] if len(fields) >= 4 else None}
                    regions.append(region)
                except (IndexError, ValueError):
                    LOG.warning(f"Skipping malformed BED line: {line}", file=sys.stderr)
                    continue
    return regions

#############################################################################

def getMAFHeader(maf_file, maf_compression):
    """Return header lines (starting with ##) from the MAF file, skipping blank lines."""
    headers = []
    with COMMON.openMaf(maf_file, maf_compression, "rt") as fp:
        for line in fp:
            line = line.strip()
            if not line:  # Skip blank lines
                continue
            if line.startswith("##"):
                headers.append(line)
            else:
                break
    # print(f"Found {len(headers)} header lines in MAF file.")
    # print(f"Header lines:\n{headers}")
    # sys.exit();
    return "\n".join(headers) + "\n"

#############################################################################

def speciesFromSrc(src):
    return src.split(".", 1)[0] if "." in src else src


def scaffoldFromSrc(src):
    """
    The source-sequence part of a MAF "species.scaffold" src, or "" if the src
    carries no scaffold at all. Mirrors gc.chromFromSrc, except that a src with
    no "." yields "" rather than echoing the species back -- callers use this to
    decide whether there is a scaffold to put in a header, and echoing the
    species would produce "species.species".
    """
    return src.split(".", 1)[1] if "." in src else ""

